from pathlib import Path
s=Path('astra-remaining-improvements/stage/b415b13a50ee');p=s/'tests/worker-reliability.test.js';p.write_text(r'''
import test, { beforeEach } from 'node:test';
import assert from 'node:assert/strict';
let stored, alarm, windows, created, removed, writes, faults, scheduled;
const events={};const event=name=>({addListener(handler){events[name]=handler;}});
globalThis.chrome={
 runtime:{id:'isolated-interlude',getURL:p=>'chrome-extension://isolated-interlude/'+p,onMessage:event('message'),onStartup:event('startup'),onInstalled:event('installed'),openOptionsPage:async()=>{}},
 storage:{local:{get:async()=>structuredClone(stored),set:async patch=>{writes++;if(faults.write===writes)throw new Error('Injected storage failure');stored={...stored,...structuredClone(patch)};}}},
 alarms:{get:async()=>alarm,clear:async()=>{alarm=null;},create:async(name,value)=>{if(faults.alarm){faults.alarm=false;throw new Error('Injected alarm failure');}scheduled++;alarm={name,scheduledTime:value.when};},onAlarm:event('alarm')},
 windows:{create:async options=>{if(faults.create){faults.create=false;throw new Error('Injected create failure');}const win={id:created.length+1};created.push(options);windows.set(win.id,win);return win;},get:async id=>{if(!windows.has(id))throw new Error('Missing');return windows.get(id);},remove:async id=>{if(faults.remove){faults.remove=false;throw new Error('Injected remove failure');}removed.push(id);windows.delete(id);},onRemoved:event('removed')},
 action:{onClicked:event('action')}
};
await import('../extension/background.js');
const send=message=>new Promise(resolve=>events.message(message,{id:chrome.runtime.id},resolve));
beforeEach(()=>{stored={};alarm=null;windows=new Map();created=[];removed=[];writes=0;faults={};scheduled=0;});
test('partial settings patches persist complete validated snapshots',async()=>{const result=await send({type:'settings',settings:{focus:25},expectedRevision:0});assert.equal(result.settings.focus,25);assert.equal(result.settings.breakMinutes,5);assert.equal(stored.revision,1);assert.equal(stored.state.total,1500000);assert.deepEqual(stored.presets,[]);});
test('competing same-revision settings writes have one accepted winner',async()=>{const results=await Promise.all(['First','Second'].map(message=>send({type:'settings',settings:{message},expectedRevision:0})));assert.equal(results.filter(r=>r.error).length,1);assert.equal(stored.revision,1);assert.equal(stored.settings.message,'First');});
test('worker validates settings types instead of accepting arbitrary patch fields',async()=>{const initial=await send({type:'read'});const result=await send({type:'settings',settings:{fullscreen:'false'},expectedRevision:0});assert.match(result.error,/Invalid fullscreen/);assert.deepEqual(stored,{});assert.equal(initial.settings.fullscreen,true);});
test('saved-message CRUD is persisted while active reminder remains independent',async()=>{const preset={id:'water',title:'Water',message:'Take a sip'};await send({type:'preset',action:'create',preset,expectedRevision:0});await send({type:'preset',action:'update',id:'water',preset:{...preset,title:'Hydrate'},expectedRevision:1});assert.equal(stored.presets[0].title,'Hydrate');const active=stored.settings.message;await send({type:'preset',action:'delete',id:'water',expectedRevision:2});assert.deepEqual(stored.presets,[]);assert.equal(stored.settings.message,active);});
test('failed initial persistence produces no alarm or window effect',async()=>{faults.write=1;const result=await send({type:'command',command:'break'});assert.ok(result.error);assert.deepEqual(stored,{});assert.equal(created.length,0);assert.equal(alarm,null);});
test('alarm failure reports accepted data and later read repairs scheduling without restart',async()=>{faults.alarm=true;const result=await send({type:'command',command:'start'});assert.match(result.warning,/was saved/);const deadline=stored.state.deadline;assert.equal(stored.state.running,true);assert.equal(alarm,null);const repaired=await send({type:'read'});assert.equal(repaired.warning,undefined);assert.equal(alarm.scheduledTime,deadline);assert.equal(stored.state.deadline,deadline);});
test('failed break-window creation is repaired on the next read',async()=>{faults.create=true;const result=await send({type:'command',command:'break'});assert.ok(result.warning);assert.equal(stored.state.phase,'break');assert.equal(stored.state.breakWindow,null);await send({type:'read'});assert.equal(windows.size,1);assert.equal(stored.state.breakWindow,1);});
test('failed window-ID persistence closes the new orphan before retry',async()=>{faults.write=2;const result=await send({type:'command',command:'break'});assert.ok(result.warning);assert.equal(windows.size,0);assert.deepEqual(removed,[1]);assert.equal(stored.state.breakWindow,null);await send({type:'read'});assert.equal(windows.size,1);assert.equal(stored.state.breakWindow,2);});
test('failed window removal retains its ID for a later repair',async()=>{await send({type:'command',command:'break'});faults.remove=true;const result=await send({type:'command',command:'snooze'});assert.ok(result.warning);assert.equal(stored.state.phase,'focus');assert.equal(stored.state.breakWindow,1);const deadline=stored.state.deadline;await send({type:'read'});assert.equal(windows.size,0);assert.equal(stored.state.breakWindow,null);assert.equal(stored.state.deadline,deadline);});
test('repeated reads do not duplicate a live break window or stable alarm',async()=>{await send({type:'command',command:'break'});const scheduledBefore=scheduled;await send({type:'read'});await send({type:'read'});assert.equal(created.length,1);assert.equal(scheduled,scheduledBefore);});
test('malformed persisted state is preserved and no effects are attempted',async()=>{stored={settings:{focus:'wrong'},state:{phase:'broken'}};const before=structuredClone(stored),result=await send({type:'read'});assert.ok(result.error);assert.deepEqual(stored,before);assert.equal(created.length,0);assert.equal(scheduled,0);});
test('messages from another extension are ignored before any work',()=>{let replied=false;const result=events.message({type:'command',command:'break'},{id:'other-extension'},()=>{replied=true;});assert.equal(result,false);assert.equal(replied,false);assert.equal(writes,0);});
'''.strip()+'\n',encoding='utf-8');print('12 worker failure and concurrency cases written')
